}

public void protectedWalk(DocumentCollection coll) throws NotesException {
  Document doc = null;
  try {
    doc = coll.getFirstDocument();
    while (doc != null) {
      Document next = coll.getNextDocument(doc);
      doc.recycle();
      doc = next;
    }
  } finally {
    if (doc != null) doc.recycle();
  }
}
